.app-header {
  display: grid;
  grid-template-columns: 50px minmax(0, 1fr) minmax(0, auto);
  grid-template-rows: minmax(calc(var(--split-header-height) - 6px), auto);
  align-items: center;
  padding: 6px 16px 0 0;
  background: var(--surface);
}

.app-header > .header-row {
  grid-column: 1 / -1;
  padding-left: 50px;
}

.header-alert {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 12px;
  margin: 0 0 6px;
  font-size: var(--type-body);
  color: var(--danger);
}

/* Ghost glyph button: Graphite at rest, Paper White on hover/focus. */
.header-glyph {
  flex: 0 0 auto;
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 4px;
  color: var(--icon-muted);
  cursor: pointer;
}

.header-glyph:hover:not(:disabled),
.header-glyph:focus-visible,
.header-glyph[aria-pressed='true'] {
  color: var(--text-primary);
}

.header-glyph:disabled {
  opacity: 0.45;
  cursor: default;
}

/* While the previous thread is held for a fast J/K swap the actions stay
   disabled (never actionable) but do not dim: dimming for under 120ms is a
   flicker. They dim only once the loading presentation shows. */
.header-glyph.header-glyph-held:disabled {
  opacity: 1;
}

.header-glyph-icon {
  width: 1rem;
  height: 1rem;
}

.header-menu {
  justify-self: start;
  margin-left: 7px;
}
}

.header-tabs {
  display: flex;
  align-items: baseline;
  gap: 18px;
  min-width: 0;
  overflow: hidden;
  /* Room for the focus ring of the first tab inside the clipped line. */
  padding: 4px 4px 4px 0;
  margin: -4px 0;
}

.app-title,
.split-tab {
  font-size: var(--type-headline);
  font-weight: var(--weight-regular);
  line-height: var(--leading-headline);
}

.app-title {
  margin: 0;
  min-width: 0;
  flex: 0 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-primary);
}

.app-title-account {
  font-size: var(--type-body);
  color: var(--text-secondary);
}

.split-nav {
  display: flex;
  align-items: baseline;
  gap: 18px;
  min-width: 0;
}

.split-tab {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  min-width: 0;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 2px;
  color: var(--text-tertiary);
  white-space: nowrap;
  cursor: pointer;
}

.split-tab:hover,
.split-tab[aria-current='page'] {
  color: var(--text-primary);
}

.split-tab:focus-visible {
  outline-offset: 2px;
}

.split-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.split-count {
  flex: 0 0 auto;
  font-size: var(--type-count);
  line-height: 1;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

/* Active list filter, in words beside the tabs. */
.header-filter {
  flex: 0 0 auto;
  font-size: var(--type-body);
  color: var(--text-secondary);
  white-space: nowrap;
}

.header-trail {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-width: 0;
}

/* Compact one-line notes; they give up width before the glyphs do. */
.header-note {
  flex: 0 1 auto;
  min-width: 0;
  margin: 0 12px 0 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--type-body);
  color: var(--text-secondary);
}

.preview-tag {
  color: var(--warning);
}

/* Armed g-chord: a quiet pending hint at the trail's leading edge. */
.chord-hint {
  flex: 0 0 auto;
  margin: 0 12px 0 0;
  font-size: var(--type-body);
  color: var(--text-secondary);
  white-space: nowrap;
}

.chord-hint:empty {
  display: none;
  border-radius: 9999px;
  background: var(--rail-well);
}

.rail-utilities {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

/*
 * The label is the button's accessible name (textContent) and, on keyboard
 * focus, a tooltip beside the rail; pointer hover uses the native title, as
 * the header glyphs do. Visually hidden otherwise.
 */
.rail-label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.rail-item:focus-visible > .rail-label {
  left: calc(100% + 10px);
  top: 50%;
  width: auto;
  height: auto;
  overflow: visible;
/*
 * Contact context column (DESIGN.md "Contact Pane"): 272px on Deep Umber with
 * a 24px inset. The name is centered on the split-tab line and the email on
 * the first list line; recent cached mail runs at a 24px pitch. These pinned
 * lines apply to the wide column only; the narrow disclosure stacks them.
 */
.contact-column {
  border-left: 1px solid var(--divider);
  background: var(--surface-contact);
  overflow-y: auto;
  padding: 0 var(--contact-inset) var(--contact-inset);
  min-height: 0;
  min-width: 0;
}

.contact-identity {
  margin: 0;
}

/* One line per identity field: the value, then its copy glyph. The glyph
   sits in the line's trailing slot, so a hidden glyph never adds a line. */
.contact-line {
  display: flex;
  align-items: center;
  gap: 4px;
  margin: 0;
  min-width: 0;
}

.contact-line > :first-child {
  min-width: 0;
  overflow-wrap: anywhere;
}

/* Name: centered on the tab line within a header-height block; a long name
   wraps around that center before it pushes the email down. */
.contact-column .contact-line-name,
.contact-column .contact-unknown {
  min-height: var(--split-header-height);
  padding-top: 6px;
}

.contact-column .contact-unknown {
  display: flex;
  align-items: center;
}

/* Email: the 36px line after the header block, i.e. the first list line. */
.contact-column .contact-line-mailbox {
  min-height: 36px;
}

/* Headline: the contact name is the pane's one large line. */
.contact-name {
  font-size: var(--type-headline);
  font-weight: var(--weight-regular);
  line-height: var(--leading-headline);
  color: var(--text-primary);
}

